local DU=CU.xp*wU
local EU=math.min(CU.n,math.floor((xU-zU)/math.max(1,DU)))
if EU>0 then
yU[CU.id]=EU
zU=zU+EU*DU
AU=AU+EU
end
end
return{feed=yU,planned=zU,n=AU}
end
