Pdb(yvd[2313]..Mdb.portal,math.max(0,Vdb))
F.log(1,yvd[2869],string.format(yvd[2885],W.levelName(W.PORTALS[Mdb.portal].from),Vdb,Udb,Odb,Ndb>0 and string.format(yvd[2886],Ndb,Tdb)or yvd[580]))
