ab.LAB={EVERY=3,KINDS={story=true,raid=true,infinite=true},MIN_EVIDENCE=5,AGAIN=24*3600}
function ab.unitEvidence(Rfb)
local Sfb=P.learn[Rfb]
local Tfb=Sfb and tonumber(Sfb.n)or 0
local Ufb=db.hive()
local Vfb=Ufb and type(Ufb.units)==yvd[1655]and Ufb.units[Rfb]
if type(Vfb)==yvd[1655]then
Tfb=Tfb+(tonumber(Vfb.matches)or 0)+(tonumber(Vfb.matches3)or 0)
end
return Tfb
end
function ab.unitLabSafe(Wfb)
if O.unitLab==false or type(Wfb)~=yvd[1655]or not ab.LAB.KINDS[Wfb.kind]or Wfb.first then
return false
end
if P.trial or P.study or(type(P.testTeam)==yvd[1655]and(tonumber(P.testTeam.left)or 0)>0)or(P.train and P.train.on)or ab.partyRole()~=yvd[583]then
return false
end
local Xfb,Yfb=pcall(ab.matchOn,Wfb)
if Xfb and Yfb then
return false
end
local Zfb=type(P.unitLab)==yvd[1655]and P.unitLab or{}
if Zfb.pauseKey==Wfb.key and os.time()<(tonumber(Zfb.pauseUntil)or 0)then
return false
end
local _fb=W.rec(Wfb.key)
local agb,bgb=tonumber(_fb.runs)or 0,tonumber(_fb.wins)or 0
if Wfb.kind==yvd[1674]then
local cgb,dgb=pcall(W.infDaily,N.prof(),Wfb.level,W.infReach(Wfb.key))
return agb>=3 and cgb and(tonumber(dgb)or 1)<=0
end
return agb>=5 and(tonumber(_fb.streak)or 0)==0 and bgb/agb>=0.9
end
function ab.unitLab(egb)
if not ab.unitLabSafe(egb)then
return
end
P.unitLab=type(P.unitLab)==yvd[1655]and P.unitLab or{}
local fgb=P.unitLab
fgb.tried=type(fgb.tried)==yvd[1655]and fgb.tried or{}
fgb.seen=(tonumber(fgb.seen)or 0)+1
if fgb.seen%ab.LAB.EVERY~=0 then
return
end
local ggb=N.session()
local hgb=V.equipped()
if not ggb or#hgb<2 then
return
end
local igb={}
for jgb,kgb in ipairs(hgb)do
igb[kgb.uuid]=true
igb[kgb.id]=true
end
local lgb,mgb,ngb
for ogb,pgb in pairs(ggb.profile_data.collection.owned_units)do
local qgb=pgb.unit_id
if not igb[ogb]and not igb[qgb]and N.Units[qgb]and not V.isFarm(qgb)and not V.allyBuff(qgb)and os.time()-(tonumber(fgb.tried[qgb])or 0)>ab.LAB.AGAIN then
local rgb=ab.unitEvidence(qgb)
if rgb<ab.LAB.MIN_EVIDENCE then
local sgb=ggb.collection:get_unit_by_uuid(ogb)or pgb
local tgb=jb.score(sgb)
if tgb>0 and(not lgb or rgb<mgb or(rgb==mgb and tgb>ngb))then
lgb,mgb,ngb={uuid=ogb,id=qgb,u=sgb},rgb,tgb
end
end
end
end
if not lgb then
return
end
local ugb,vgb
for wgb,xgb in ipairs(hgb)do
if not V.isFarm(xgb.id)and not V.allyBuff(xgb.id)and xgb.uuid~=O.evolveUnit then
local ygb=jb.score(xgb.u)
if not ugb or ygb<vgb then
ugb,vgb=xgb,ygb
end
end
end
if not ugb then
return
end
fgb.tried[lgb.id]=os.time()
local zgb=0
for Agb in pairs(fgb.tried)do
zgb=zgb+1
if zgb>300 then
fgb.tried[Agb]=nil
end
end
local Bgb,Cgb=fb.levelFor(egb)
if not Bgb then
return
end
local Dgb=fb.info(Bgb,egb.key,Cgb,egb.mod or W.ldMod(Bgb)or W.levelMod(egb.level))
local Egb={}
for Fgb,Ggb in ipairs(hgb)do
table.insert(Egb,Ggb.uuid==ugb.uuid and lgb.u or Ggb.u)
end
local Hgb,Igb=pcall(fb.run,Dgb,fb.teamFrom(Egb,Dgb.map),{hpMul=1.1})
local Jgb=Hgb and type(Igb)==yvd[1655]and(Igb.won or(Dgb.infinite and(tonumber(Igb.wave)or 0)>=0.8*W.infReach(egb.key)))
if not Jgb then
F.log(2,yvd[2911],string.format(yvd[2912],V.name(lgb.id),egb.label))
return
end
local Kgb={}
for Lgb,Mgb in ipairs(hgb)do
table.insert(Kgb,Mgb.uuid==ugb.uuid and lgb.uuid or Mgb.uuid)
end
if ab.equipTeam(Kgb,yvd[2913]..V.name(lgb.id))then
fgb.now={id=lgb.id,out=ugb.id,key=egb.key,at=os.time(),ev=mgb}
F.log(1,yvd[2911],string.format(yvd[2914],V.name(lgb.id),V.name(ugb.id),egb.label,mgb))
F.saveNow()
end
end
