function bb.holdGain(gkc,hkc)
if bb.random or not hkc or not bb.info then
return 0
end
local ikc=V.attackInfo(hkc.atk,hkc.range)
if(ikc.stun or 0)<=0 and(ikc.slowTime or 0)<=0 then
return 0
end
local jkc=0
for kkc,lkc in ipairs(bb.mine or{})do
local mkc=lkc._stats
local nkc=V.rows(mkc.id.Value)
local okc=nkc and nkc[math.min(mkc.upgrade.Value,nkc.max)]
local pkc=okc and okc.atk and V.attackInfo(okc.atk,okc.range)
if pkc and((pkc.stun or 0)>0 or(pkc.slowTime or 0)>0)then
jkc=jkc+1
end
end
local qkc,rkc=fb.mask(bb.info.map,V.range(gkc.u,0)*(bb.info.rangeScale or 1)),0
for skc=1,fb.BINS do
if qkc[skc]then
rkc=rkc+1
end
end
local tkc=bb.depth and bb.depth.units>0 and bb.depth.covEnd or 1
local ukc=(V.airFrom(gkc.id)==0)and 1 or(1-(1-N.FLY_GROUND)*math.min(1,bb.info.flyChance or 0))
return eb.holdGain(ikc,bb.teamDps or 0,rkc/(math.max(0.1,tkc)*fb.BINS)*ukc,jkc)
end
function bb.buffGain(vkc)
local wkc=V.allyBuff(vkc.id)
if not wkc then
return 0
end
local xkc=bb.buffShort(wkc)
local ykc=P.stack[wkc.attack]
local zkc=ykc and ykc.stacks and(ykc.cap or 1)or nil
local Akc,Bkc=pcall(V.range,vkc.u,0)
Bkc=(Akc and tonumber(Bkc)or 15)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local Ckc=zkc and O.community and tonumber(wkc.time)and tonumber(wkc.cd)
local function Dkc(Ekc,Fkc)
local Gkc=math.floor(Ekc*wkc.time/math.max(1,wkc.cd)+0.001)
return math.min(zkc,(1+Fkc)^Gkc-1)
end
local Hkc=0
for Ikc,Jkc in ipairs(xkc)do
local Kkc=0
for Lkc,Mkc in ipairs(xkc)do
if(Mkc.pos-Jkc.pos).Magnitude<=Bkc then
local Nkc=wkc.types[Mkc.base]
local Okc=Nkc*wkc.uptime
if Ckc then
local Pkc,Qkc=Dkc(Mkc.n,Nkc),Mkc.n+1
while Qkc<Mkc.n+6 and Dkc(Qkc,Nkc)<=Pkc+0.001 do
Qkc=Qkc+1
end
Okc=math.max(0,(Dkc(Qkc,Nkc)-Pkc)/(Qkc-Mkc.n))
elseif zkc then
Okc=math.max(0,math.min(zkc,(Mkc.n+1)*Nkc*wkc.uptime)-math.min(zkc,Mkc.n*Nkc*wkc.uptime))
end
Kkc=Kkc+Mkc.dps*Okc
end
end
Hkc=math.max(Hkc,Kkc)
end
return Hkc*(Ckc and 1 or 0.7)
end
