function bb.learn()
local qsc=bb.calRun and bb.calRun.potBy
if type(qsc)~=yvd[1655]then
return
end
pcall(bb.sampleHelpers,true)
local rsc={}
for ssc,tsc in pairs(bb.ownDealt or{})do
if not V.isFarm(tsc.id)then
rsc[tsc.id]=(rsc[tsc.id]or 0)+(tonumber(tsc.v)or 0)
end
end
for usc,vsc in pairs(bb.helperDealt or{})do
if vsc.owner and V.SUMMONER[vsc.owner]then
rsc[vsc.owner]=(rsc[vsc.owner]or 0)+(tonumber(vsc.v)or 0)
end
end
local wsc,xsc=0,0
for ysc,zsc in pairs(qsc)do
if zsc>0 then
wsc=wsc+(rsc[ysc]or 0)
xsc=xsc+zsc
end
end
if wsc<=0 or xsc<=0 then
return
end
local Asc=wsc/xsc
bb.lastEff={}
for Bsc,Csc in pairs(qsc)do
if Csc>0 and Csc/xsc>0.02 then
local Dsc=P.learn[Bsc]or{eff=1,n=0,v=3}
if(tonumber(Dsc.v)or 0)<3 then
Dsc.eff,Dsc.v=(tonumber(Dsc.eff)or 1)*V.effRescale(Bsc),3
end
local Esc=math.max(0.02,0.25*math.sqrt(30/(30+Dsc.n)))
local Fsc=U.clamp(((rsc[Bsc]or 0)/Csc)/Asc,0.2,6)
bb.lastEff[Bsc]=math.floor(Fsc*1000+0.5)/1000
Dsc.eff=Dsc.eff+(Fsc-Dsc.eff)*Esc
Dsc.n=Dsc.n+1
P.learn[Bsc]=Dsc
end
end
local Gsc=V.mapKey((bb.info and bb.info.map)or(bb.ld and bb.ld.map),(bb.info and bb.info.mapSig)or V.mapSig(bb.ld))
if Gsc and next(bb.lastEff)then
P.mapLearn=type(P.mapLearn)==yvd[1655]and P.mapLearn or{}
local Hsc=type(P.mapLearn[Gsc])==yvd[1655]and P.mapLearn[Gsc]or{}
for Isc,Jsc in pairs(bb.lastEff)do
local Ksc=type(Hsc[Isc])==yvd[1655]and Hsc[Isc]or{eff=Jsc,n=0}
local Lsc=math.max(0.1,0.5*math.sqrt(4/(4+(tonumber(Ksc.n)or 0))))
Ksc.eff=(tonumber(Ksc.n)or 0)==0 and Jsc or((tonumber(Ksc.eff)or Jsc)+(Jsc-(tonumber(Ksc.eff)or Jsc))*Lsc)
Ksc.n=(tonumber(Ksc.n)or 0)+1
Hsc[Isc]=Ksc
end
Hsc._at=os.time()
P.mapLearn[Gsc]=Hsc
if U.count(P.mapLearn)>80 then
local Msc,Nsc
for Osc,Psc in pairs(P.mapLearn)do
if not Nsc or(tonumber(Psc._at)or 0)<Nsc then
Msc,Nsc=Osc,tonumber(Psc._at)or 0
end
end
P.mapLearn[Msc]=nil
end
end
end
