Uuc=Uuc and Uuc[0]
if Uuc and not V.isFarm(Tuc.id)then
Quc=math.max(Quc,V.dps(Tuc.u,0,bb.mod)*(tonumber(Uuc.cd)or 2)/math.max(1,V.attackInfo(Uuc.atk,Uuc.range).n))
