function bb.focusSpot(Yzc)
local Zzc=bb.focus
local _zc=V.range(Yzc.u,0)*((bb.info and bb.info.rangeScale)or 1)
local aAc=U.flat(Zzc.pos)
local bAc,cAc
local dAc=0
for eAc,fAc in ipairs(bb.cands)do
if(U.flat(fAc)-aAc).Magnitude<=_zc then
local gAc=bb.valid(fAc,Yzc.data)
dAc=dAc+1
if dAc%40==0 then
task.wait()
end
if gAc then
local hAc,iAc=0,U.flat(gAc)
for jAc,kAc in ipairs(bb.samples)do
if kAc.prog>=Zzc.prog and(U.flat(kAc.pos)-iAc).Magnitude<=_zc then
hAc=hAc+1
end
end
if not cAc or hAc>cAc then
bAc,cAc=gAc,hAc
end
end
end
end
return bAc,cAc or 0
end
function bb.focusGain(lAc)
