end
local nAc=lAc._stats
if not nAc:FindFirstChild(yvd[1820])then
return 1
end
local oAc,pAc=U.flat(lAc:GetPivot().Position),nAc.range.Value
if mAc.fly and not bb.canAir(lAc)then
return 0.02
end
if(oAc-U.flat(mAc.pos)).Magnitude<=pAc then
return 1
end
return(oAc-U.flat(mAc.pos)).Magnitude<=pAc*1.5 and 0.3 or 0.02
end
bb.cashTried=setmetatable({},{__mode=yvd[1869]})
function bb.lastWaveCash()
